"""Write the extension icons. Stdlib only."""
import base64
import pathlib

ICONS = {
    "icon16.png": "iVBORw0KGgoAAAANSUhEUgAAABAAAAAQCAYAAAAf8/9hAAAAP0lEQVR42mNgoCYQVTD+TwymSDNWQ0jVjGEIsRpevPsOxngNqNvxH4wHhwHoGuhvwMCEAcXRSLfUSP3MRC4AADGlR5jR4g9qAAAAAElFTkSuQmCC",
    "icon48.png": "iVBORw0KGgoAAAANSUhEUgAAADAAAAAwCAYAAABXAvmHAAAAlElEQVR42u3ZsQ2AMAxE0SxBzw7sx1yMREVLGXqkoCQkxD7+Se7vSSCEHQIhpCjTvMSe47J0V8yo8k0Qo8u/QlgpX4WwVr4YAWAkwGr5bMTXhfbjTE5zwLrFxwEAAAAAAN0AqUJmAbml3AHuxQDwCKm+xHwHAAAAAEDvp57dEJu5vwDcr9clDhwSJyaJI5/EmZUQ4Vy7PwwYUPYOzwAAAABJRU5ErkJggg==",
    "icon128.png": "",
}

def main():
    root = pathlib.Path(__file__).resolve().parents[1] / "icons"
    root.mkdir(exist_ok=True)
    for name, payload in ICONS.items():
        (root / name).write_bytes(base64.b64decode(payload))
        print(name)

if __name__ == "__main__":
    main()
